define([],function(){return{init:function(formid){const form=document.getElementById(formid);if(!form){return}const preset=form.querySelector("[name=periodpreset]");const from=form.querySelector("[name=periodfromdate]");const to=form.querySelector("[name=periodtodate]");const apply=form.querySelector("button[type=submit]");const update=function(){const custom=preset.value==="custom";const option=preset.options[preset.selectedIndex];if(!custom){from.value=option.dataset.from;to.value=option.dataset.to}from.disabled=!custom;to.disabled=!custom;apply.disabled=custom&&(!from.value||!to.value||from.value>to.value)};preset.addEventListener("change",update);from.addEventListener("change",update);to.addEventListener("change",update);update()}}});